import XCTest
@MainActor final class CompanionEditorJourneyTests:XCTestCase {
 private func tap(_ id:String,_ app:XCUIApplication){let b=app.buttons[id];XCTAssertTrue(b.waitForExistence(timeout:12),id);for _ in 0..<8 where !b.isHittable{app.swipeUp(velocity:.slow)};XCTAssertTrue(b.isHittable,id);b.tap()}
 private func photo(_ name:String,_ app:XCUIApplication){let a=XCTAttachment(screenshot:app.screenshot());a.name=name;a.lifetime = .keepAlways;add(a)}
 private func journey(_ language:String,_ theme:String){
  continueAfterFailure=false;let app=XCUIApplication();app.launchEnvironment=["PIYALI_OFFLINE_TESTS":"1","PIYALI_TEST_IDENTITY_SCOPE":UUID().uuidString,"PIYALI_ENTRY_INITIAL_LANGUAGE":language,"PIYALI_ENTRY_INITIAL_THEME":theme,"PIYALI_SETTINGS_FIXTURE":"1","PIYALI_HEADLINE_FIXTURE":"failure"];app.launchArguments=["-AppleLanguages","(en)","-AppleLocale","en_US"];app.launch();let entry=app.textFields["entryName"];XCTAssertTrue(entry.waitForExistence(timeout:15));entry.tap();entry.typeText("Companion Learner");tap("entryKeyboardDone",app);tap("createAccount",app);tap("startLearning",app);tap("focusCustomizeCompanion",app)
  let field=app.textFields["companionNameDraft"];XCTAssertTrue(field.waitForExistence(timeout:8));let initial=field.value as? String ?? "";XCTAssertEqual(app.scrollViews["companionCustomizeDialog"].frame.height,628,accuracy:2);XCTAssertTrue(app.buttons["companionOption-ghost"].isEnabled);XCTAssertTrue(app.buttons["companionOption-ghost"].isSelected);XCTAssertFalse(app.buttons["companionOption-alien"].isEnabled);XCTAssertFalse(app.buttons["companionOption-axolotl"].isEnabled);XCTAssertEqual(app.buttons["companionOption-ghost"].frame.width,153,accuracy:1);XCTAssertEqual(app.buttons["companionOption-ghost"].frame.height,116,accuracy:1);XCTAssertEqual(app.buttons["companionCancel"].frame.height,40,accuracy:1);photo("Companion Home editor "+language,app)
  field.tap();field.typeText("Discard me");tap("companionCancel",app);tap("focusCustomizeCompanion",app);XCTAssertTrue(field.waitForExistence(timeout:8));XCTAssertEqual(field.value as? String,initial);field.tap();field.typeText("abcdefghijklmnopqrstuvwxyz");XCTAssertEqual(field.value as? String,"abcdefghijklmnopqrstuvwx");field.typeText("\n");XCTAssertTrue(app.buttons["focusCustomizeCompanion"].waitForExistence(timeout:8));XCTAssertTrue(app.staticTexts["abcdefghijklmnopqrstuvwx"].exists);photo("Companion bounded name saved "+language,app)
  tap("openDailyGoal",app);tap("goalCompanionEdit",app);XCTAssertTrue(field.waitForExistence(timeout:8));XCTAssertEqual(field.value as? String,"abcdefghijklmnopqrstuvwx");XCTAssertEqual(app.scrollViews["companionCustomizeDialog"].frame.height,668,accuracy:2);XCTAssertFalse(app.buttons["dailyGoalSave"].exists && app.buttons["dailyGoalSave"].isHittable);photo("Companion nested Goal editor "+language,app);field.tap();field.typeText(String(repeating:XCUIKeyboardKey.delete.rawValue,count:24)+"\n");XCTAssertTrue(app.buttons["dailyGoalClose"].waitForExistence(timeout:8));tap("dailyGoalClose",app)
  app.terminate();app.launch();XCTAssertTrue(app.buttons["productMenu"].waitForExistence(timeout:15));tap("focusCustomizeCompanion",app);XCTAssertTrue(field.waitForExistence(timeout:8));XCTAssertEqual(field.value as? String,initial,"Clearing the name restores the localized default after relaunch");photo("Companion clear restored "+language,app);app.coordinate(withNormalizedOffset:CGVector(dx:0.005,dy:0.5)).tap();XCTAssertFalse(field.exists,"Outside dismissal discards the draft and returns to Home")
 }
 func testHomeAndNestedGoalCancelBoundSaveClearOutsideDismissAndRelaunchEnglish(){journey("en","light")}
 func testHomeAndNestedGoalCancelBoundSaveClearOutsideDismissAndRelaunchArabic(){journey("ar","dark")}
}
